// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_input: bool,
  pub api_manualActuatorInput: bool,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_input(container.api_input);
  put_manualActuatorInput(container.api_manualActuatorInput);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  input: bool,
  manualActuatorInput: bool)
{
  put_input(input);
  put_manualActuatorInput(manualActuatorInput);
}

/// setter for IN DataPort
pub fn put_input(value: bool)
{
  *extern_api::IN_input.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_manualActuatorInput(value: bool)
{
  *extern_api::IN_manualActuatorInput.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_output() -> bool
{
  return extern_api::OUT_output.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
